import {e,state} from '../lib.js';
export const nav=[['/app','تطبيق OnStar'],['/cloud','OnStar Cloud'],['/knowledge','مركز المعرفة'],['/services','خدمات الفريق']];
export function header(path){const account=state.me?.customer;return `<header class="site-header"><div class="shell head-inner"><a href="/" data-link class="brand" aria-label="الصفحة الرئيسية OnStar"><span class="brand-symbol"><span></span><span></span><span></span></span><span class="brand-word">ONSTAR<small>NETWORK ECOSYSTEM</small></span></a><nav class="desktop-nav" aria-label="التنقل الرئيسي">${nav.map(([href,l])=>`<a href="${href}" data-link class="${path===href?'active':''}">${l}</a>`).join('')}</nav><div class="head-cta"><a class="login-link" data-link href="${account?'/account':'/customer-login'}">${account?'لوحة التحكم':'دخول المشترك'}</a><a class="mini-arrow" href="/cloud" data-link aria-label="استكشاف OnStar Cloud">↗</a></div><button class="menu-button" id="menu-button" aria-expanded="false" aria-controls="mobile-menu" aria-label="فتح القائمة"><span></span><span></span><span></span></button></div><nav class="mobile-menu" id="mobile-menu" aria-label="التنقل على الهاتف" hidden>${nav.map(([href,l])=>`<a href="${href}" data-link>${l}<span>↖</span></a>`).join('')}<a href="${account?'/account':'/customer-login'}" data-link>${account?'لوحة المشترك':'تسجيل الدخول'}<span>↖</span></a></nav></header>`}
export function footer(){const c=state.content;return `<footer class="footer"><div class="shell"><div class="footer-top"><div><div class="footer-big">شبكتك،<br/><em>بلا حدود.</em></div><p>من إدارة الشبكة على هاتفك، إلى الوصول إلى أجهزتك عن بُعد.</p></div><div class="footer-links"><div><strong>المنتجات</strong><a data-link href="/app">تطبيق OnStar</a><a data-link href="/cloud">OnStar Cloud</a><a data-link href="/register">الاشتراك</a></div><div><strong>المساعدة</strong><a data-link href="/knowledge">مركز المعرفة</a><a data-link href="/faq">الأسئلة الشائعة</a><a data-link href="/contact">تواصل معنا</a></div></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} OnStar. جميع الحقوق محفوظة.</span><span>DESIGNED FOR THE NETWORKS THAT CONNECT US</span></div></div></footer>`}
export function frame(body,path,opts={}){return `${header(path)}<main id="main" tabindex="-1">${body}</main>${footer()}`}
export const sectionHeader=(eyebrow,title,desc='')=>`<div class="section-heading"><span class="eyebrow">${e(eyebrow)}</span><h2>${title}</h2>${desc?`<p>${e(desc)}</p>`:''}</div>`;
